**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
using namespace std;

int main() {
    ifstream plik("dane.txt");
    int n;
    int max3 = -1, min7 = -1;
    bool zn3 = false, zn7 = false;

    while (plik >> n) {
        if (n % 3 == 0) {
            if (!zn3 || n > max3) { max3 = n; zn3 = true; }
        }
        if (n % 7 == 0) {
            if (!zn7 || n < min7) { min7 = n; zn7 = true; }
        }
    }

    cout << "a) Najwieksza podzielna przez 3: ";
    if (zn3) cout << max3 << endl;
    else cout << "brak" << endl;

    cout << "b) Najmniejsza podzielna przez 7: ";
    if (zn7) cout << min7 << endl;
    else cout << "brak" << endl;

    return 0;
}
```

**Wyjasnienie**: Warunkowe min/max z flagami — bezpieczna inicjalizacja pierwszym elementem spelniajacym warunek zamiast INT_MIN/INT_MAX.

Weryfikacja:
- Podzielne przez 3: 45, 63, 84, 72 -> max = 84
- Podzielne przez 7: 63, 49, 35 -> min = 35
